import type {
  DocumentFinding,
  DocumentUnitRow,
  RemediationItem,
  RemediationSeverity,
  SecurityDocument,
} from '../../../types/index.js'
import { locatorLabel } from './parsers.js'
import { NewRemediationItem, SecurityReviewStore } from './store.js'

// Remediation items are generated by rule from step 2 findings, not by a model:
//   * open pen test findings with stated severity Critical or High
//   * every SOC 2 exception (severity "high" by rule; SOC 2 reports state none)
// Remediated, Medium and Low findings create nothing; access review exceptions are evidence
// for the SOC 2 exception they belong to, not separate items.
// Due date = finding date + the vendor's own policy SLA for that severity.

const MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']
const DATE = new RegExp(`\\b(${MONTHS.join('|')}) (\\d{1,2}), (\\d{4})\\b`, 'gi')

const flat = (s: string) => s.replace(/\s+/g, ' ')

function iso(month: string, day: string, year: string): string {
  return `${year}-${String(MONTHS.indexOf(month.toLowerCase()) + 1).padStart(2, '0')}-${day.padStart(2, '0')}`
}

function datesIn(text: string): string[] {
  return [...flat(text).matchAll(DATE)].map((m) => iso(m[1], m[2], m[3]))
}

export function addDays(date: string, days: number): string {
  const d = new Date(`${date}T00:00:00Z`)
  d.setUTCDate(d.getUTCDate() + days)
  return d.toISOString().slice(0, 10)
}

export interface SlaPolicy {
  days: Record<Exclude<RemediationSeverity, 'low'>, number>
  basis: 'policy' | 'default'
}

const DEFAULT_SLA: SlaPolicy['days'] = { critical: 15, high: 30, medium: 90 }

// Reads "Critical vulnerabilities are remediated within 15 calendar days" style commitments
export function readSla(policyTexts: string[]): SlaPolicy {
  const found: Partial<SlaPolicy['days']> = {}
  const re = /\b(critical|high|medium)\b[a-z\s]{0,40}?\bwithin (\d+) (?:calendar )?days/gi
  for (const text of policyTexts) {
    for (const m of flat(text).matchAll(re)) {
      const sev = m[1].toLowerCase() as keyof SlaPolicy['days']
      found[sev] ??= Number(m[2])
    }
  }
  const complete = found.critical !== undefined && found.high !== undefined
  return complete ? { days: { ...DEFAULT_SLA, ...found }, basis: 'policy' } : { days: DEFAULT_SLA, basis: 'default' }
}

// The date a document was issued: an explicit "Report issued" date, else its latest full date
// that is not after asOf (a SOC 2 opinion is signed after the period it covers)
export function documentDate(units: DocumentUnitRow[], asOf: string): string | null {
  const text = flat(units.map((u) => u.text).join(' '))
  const explicit = new RegExp(`(?:report issued|issued|report date)[:\\s]+(${MONTHS.join('|')}) (\\d{1,2}), (\\d{4})`, 'i').exec(text)
  if (explicit) return iso(explicit[1], explicit[2], explicit[3])
  return datesIn(text).filter((d) => d <= asOf).sort().at(-1) ?? null
}

// "reported to Acme on August 21, 2026" in the finding's own paragraph
export function findingDate(units: DocumentUnitRow[], ref: string): string | null {
  const text = flat(units.map((u) => u.text).join(' '))
  // Any finding or control ID ends the paragraph (PT-03, CC6.2, A1.2)
  const refRe = /\b(?:[A-Z]{2,4}-\d+|CC\d+\.\d+|A\d+\.\d+)\b/g
  let i = text.indexOf(ref)
  while (i >= 0) {
    refRe.lastIndex = i + ref.length
    const next = refRe.exec(text)
    const paragraph = text.slice(i, next ? next.index : undefined)
    const m = new RegExp(`(?:reported|identified|discovered)[^.]{0,40}? on (${MONTHS.join('|')}) (\\d{1,2}), (\\d{4})`, 'i').exec(paragraph)
    if (m) return iso(m[1], m[2], m[3])
    i = text.indexOf(ref, i + ref.length)
  }
  return null
}

interface Candidate {
  ref: string
  finding: DocumentFinding
  severity: RemediationSeverity
  doc: SecurityDocument
}

export function remediationCandidates(findings: DocumentFinding[], docs: SecurityDocument[]): Candidate[] {
  const docOf = new Map(docs.map((d) => [d.id, d]))
  const out: Candidate[] = []
  const seen = new Set<string>()
  const add = (f: DocumentFinding, severity: RemediationSeverity) => {
    const doc = docOf.get(f.document_id)
    if (!doc || !f.ref || seen.has(`${doc.id}|${f.ref}`)) return
    seen.add(`${doc.id}|${f.ref}`)
    out.push({ ref: f.ref, finding: f, severity, doc })
  }
  for (const f of findings) {
    if (f.kind !== 'pentest_finding' || f.status !== 'open') continue
    const sev = (f.stated_severity ?? '').toLowerCase()
    if (sev === 'critical' || sev === 'high') add(f, sev)
  }
  // Prefer the exception record (it carries the auditor's text); fall back to the control
  for (const f of findings) if (f.kind === 'control_exception') add(f, 'high')
  for (const f of findings) if (f.kind === 'control' && f.status === 'exceptions_noted') add(f, 'high')
  return out
}

export interface GenerateResult {
  created: number
  kept: number
  replaced: number
  sla: SlaPolicy
}

export async function generateRemediation(
  store: SecurityReviewStore,
  ctx: { supplierId: string; requestId: string; userId: string | null; asOf: string },
): Promise<GenerateResult> {
  const docs = (await store.listDocuments(ctx.requestId)).filter((d) => d.role === 'evidence')
  const findings = await store.listFindings(docs.map((d) => d.id))
  const unitsOf = new Map<string, DocumentUnitRow[]>()
  const units = async (docId: string) => {
    if (!unitsOf.has(docId)) unitsOf.set(docId, await store.listUnits(docId))
    return unitsOf.get(docId)!
  }
  const policyTexts: string[] = []
  for (const d of docs.filter((x) => x.doc_type === 'security_policy')) policyTexts.push(...(await units(d.id)).map((u) => u.text))
  const sla = readSla(policyTexts)
  const owner = await store.getOwnerContact(ctx.supplierId)

  // Untouched generated items are replaced; anything a person started, closed or linked is kept
  const existing = await store.listRemediation(ctx.requestId)
  const replaceable = existing.filter((r) => r.source === 'ai' && r.status === 'open' && !r.external_key)
  const kept = existing.filter((r) => !replaceable.includes(r))
  const keptRefs = new Set(kept.map((r) => r.title.split(':')[0].trim()))

  const items: NewRemediationItem[] = []
  for (const c of remediationCandidates(findings, docs)) {
    if (keptRefs.has(c.ref)) continue
    const u = await units(c.doc.id)
    const own = findingDate(u, c.ref)
    const start = own ?? documentDate(u, ctx.asOf)
    const days = c.severity === 'low' ? null : sla.days[c.severity]
    const due = start && days !== null ? addDays(start, days) : null
    const basis = own ? 'date the finding was reported' : 'report date'
    const description = [
      c.finding.detail ?? c.finding.title,
      c.finding.quote ? `Evidence: "${c.finding.quote}" (${c.doc.filename}, ${locatorLabel(c.finding.locator)})` : null,
      c.finding.kind === 'pentest_finding'
        ? `Severity as stated in the pen test: ${c.finding.stated_severity}.`
        : 'Auditor exception in the SOC 2 report; SOC 2 states no severity, so it is rated high by rule.',
      due ? `Due ${due}: ${days} days (${sla.basis === 'policy' ? 'vendor policy SLA' : 'default SLA — no policy SLA found'}) after ${start} (${basis}).`
        : 'No due date: no date found for this finding.',
    ].filter(Boolean).join('\n')
    items.push({
      supplier_id: ctx.supplierId, request_id: ctx.requestId, finding_id: c.finding.id,
      title: `${c.ref}: ${c.finding.title}`.slice(0, 200), description, severity: c.severity,
      owner_contact_id: owner?.id ?? null, owner_name: owner?.name ?? null, status: 'open', due_date: due,
      source: 'ai', external_key: null,
    })
  }

  await store.deleteRemediation(replaceable.map((r) => r.id))
  await store.insertRemediation(items)
  await store.logEvent({
    supplier_id: ctx.supplierId, request_id: ctx.requestId, actor: 'system', actor_id: null,
    event_type: 'remediation_generated', entity_type: 'remediation', entity_id: null,
    payload: { created: items.length, kept: kept.length, replaced: replaceable.length, sla_basis: sla.basis },
  })
  return { created: items.length, kept: kept.length, replaced: replaceable.length, sla }
}

export const isOverdue = (r: RemediationItem, asOf: string) =>
  Boolean(r.due_date) && r.due_date! < asOf && (r.status === 'open' || r.status === 'in_progress')

// Jira CSV import columns; Jira's default priorities are Highest/High/Medium/Low
const JIRA_PRIORITY: Record<RemediationSeverity, string> = { critical: 'Highest', high: 'High', medium: 'Medium', low: 'Low' }

function csvCell(v: string): string {
  // Quote everything; neutralise leading formula characters so spreadsheets don't execute them
  const safe = /^[=+\-@\t\r]/.test(v) ? `'${v}` : v
  return `"${safe.replace(/"/g, '""')}"`
}

export function toJiraCsv(items: RemediationItem[]): string {
  const header = ['Summary', 'Description', 'Priority', 'Assignee', 'Due Date', 'Labels']
  const rows = items.map((r) => [
    r.title, r.description ?? '', JIRA_PRIORITY[r.severity], r.owner_name ?? '', r.due_date ?? '',
    ['security-review', r.title.startsWith('PT-') ? 'pentest' : 'soc2'].join(' '),
  ])
  return [header, ...rows].map((row) => row.map(csvCell).join(',')).join('\r\n') + '\r\n'
}
